import React from 'react'
import { useEffect } from 'react'
import Home from './pages/home'
import Duck from './images/Duck.png'
import './App.css'
import Box from '@mui/material/Box';
import Avatar from '@mui/material/Avatar';

import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';
import Tooltip from '@mui/material/Tooltip';



function App() {

  useEffect(() => {
    document.body.style.backgroundColor = '#061213'
  })

  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
  const open = Boolean(anchorEl);
  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };

  return (
    <div className="App">
      <header className="App-header">
        <React.Fragment>
          <Box sx={{ display: 'flex', alignItems: 'center', textAlign: 'center' }}>
            <Box sx={{ display: 'flex', alignItems: 'center', textAlign: 'center' }}>
          <img style={{ width: '50px', height: '50px'}} src={Duck} alt="duck logo"></img>
            <Typography sx={{ minWidth: 100 }}>QuackBox</Typography>
          </Box>
            <Typography sx={{ minWidth: 100 }}>Link Account</Typography>
            <Typography sx={{ minWidth: 100 }}>Games</Typography>
            <Typography sx={{ minWidth: 100 }}>About COMS</Typography>
            <Tooltip title="Account settings">
              <IconButton
                onClick={handleClick}
                size="small"
                sx={{ ml: 2 }}
                aria-controls={open ? 'account-menu' : undefined}
                aria-haspopup="true"
                aria-expanded={open ? 'true' : undefined}
              >
                <Avatar sx={{ width: 32, height: 32 }}>M</Avatar>
              </IconButton>
            </Tooltip>
          </Box>
        </React.Fragment>
      </header> 
    </div>
  );
}

export default App;
